     1	// Part "windows and doors" (parts/windows.mjs): the flats' sash windows, two oriel bays with caps, the flats' street door
     2	// with hood and FLATS sign, the stair-bay windows, the rear doors and windows, and the doors off the corridor. Every
     3	// write goes into the air the shell left open (plan.md OPENINGS); the shell's bricks and trim are never touched, so a
     4	// trim lintel or surround the shell already closed is skipped (see plan.md Notes).
     5	import { sashWindow, oriel, streetDoor } from "../vocab.mjs";
     6	import { B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
     7	
     8	// Pane connections: in a z-wall (front or rear) a pane runs along x, so it joins east and west.
     9	const PANE_EW = { north: "false", east: "true", south: "false", west: "true" };
    10	
    11	export function build(g) {
    12	  const isAir = (x, y, z) => /(^|:)(cave_)?air$/.test(g.blockAt(x, y, z)) && !g.protected?.has(`${x},${y},${z}`);
    13	  // Write one cell only if it is air; returns whether it was written.
    14	  const put = (x, y, z, block, state) => { if (!isAir(x, y, z)) return false; g.set(x, y, z, block, state); return true; };
    15	  const each = (x0, x1, y0, y1, fn) => { for (let x = x0; x <= x1; x++) for (let y = y0; y <= y1; y++) fn(x, y); };
    16	  const glassEW = (x0, x1, y0, y1, z) => each(x0, x1, y0, y1, (x, y) => put(x, y, z, "glass_pane", PANE_EW));
    17	  // A single door, two halves; `facing` is the side it faces out of the house.
    18	  const door = (x, y0, z, facing, hinge = "left") => {
    19	    put(x, y0, z, ...B.door("dark_oak", facing, "lower", hinge));
    20	    put(x, y0 + 1, z, ...B.door("dark_oak", facing, "upper", hinge));
    21	  };
    22	  const sill = (x, y, z) => put(x, y, z, ...B.slab("smooth_sandstone", "bottom"));
    23	
    24	  // ---- flats' street door (x 23..24, y 7..8, z 19) with hood, fanlight and FLATS sign ----
    25	  streetDoor(g, 23, 7, 19, { out: 1, sign: "FLATS" });
    26	
    27	  // ---- stair-bay front windows (x 23..24, y 15..17 and 19..21, z 19), sills below at z 20 ----
    28	  glassEW(23, 24, 15, 17, 19);
    29	  glassEW(23, 24, 19, 21, 19);
    30	  for (const y of [14, 18]) for (const x of [23, 24]) sill(x, y, 20);
    31	
    32	  // ---- flats' sash windows: 1 wide x 3 tall at x 5, 11, 13, 19; floor 1 at y 15, floor 2 at y 19; z 19 ----
    33	  for (const x of [5, 11, 13, 19]) {
    34	    sashWindow(g, x, 15, 19, { out: 1 });
    35	    sashWindow(g, x, 19, 19, { out: 1 });
    36	  }
    37	
    38	  // ---- oriel bays over units 1 and 2: caps, posts, apron and head from the vocab; glass re-set with its connections ----
    39	  for (const [x0, x1] of [[6, 10], [14, 18]]) {
    40	    oriel(g, x0, x1, 19, { facing: "south", y0: 14 });
    41	    // the vocab's oriel glass has no connection states (a thin post); set them here over its own panes
    42	    for (const y0 of [15, 19]) each(x0 + 1, x1 - 1, y0, y0 + 2, (x, y) => g.set(x, y, 20, "glass_pane", PANE_EW));
    43	  }
    44	
    45	  // ---- rear (north, z 2): keeper doors at x 7 and 15, stair-bay rear door at x 23 (y 7..8) ----
    46	  for (const x of [7, 15, 23]) door(x, 7, 2, "north", "left");
    47	
    48	  // ---- rear windows: 1 wide x 2 tall at y 15..16 and y 20..21 (no sills: plan gives the rear none) ----
    49	  for (const x of [6, 10, 14, 18]) for (const y0 of [15, 20]) glassEW(x, x, y0, y0 + 1, 2);
    50	  // stair-bay rear windows 2 x 2
    51	  for (const y0 of [15, 20]) glassEW(23, 24, y0, y0 + 1, 2);
    52	
    53	  // ---- doors off the corridor: stair hall (x 21, z 3) and flats (x 8 and 16, z 5) at y 14..15 and 19..20 ----
    54	  for (const y0 of [14, 19]) {
    55	    door(21, y0, 3, "east", "left");
    56	    for (const x of [8, 16]) door(x, y0, 5, "south", "left");
    57	  }
    58	}
