2-// yardWall, streetSurface. Each takes the grid and its position as arguments and writes only its own cells: into air,
3-// or over a block named by `replace` (the wall a trim sits on). Returns { placed, refused }; a refused write is counted, not thrown.
4-import { B, DIRS, OPPOSITE, plaque } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
5-
6-const id = (b) => (b.includes(":") ? b : `minecraft:${b}`);
7-const AIR = /(^|:)(cave_|void_)?air$/;
8-const matches = (r, cur) => (typeof r === "function" ? r(cur) : [r].flat().some((b) => id(b) === cur));
9-const zStep = (facing) => {
10-  if (facing !== "north" && facing !== "south") throw new Error(`facing must be north or south for a street wall (got ${facing})`);
11-  return DIRS[facing][2];
12-};
13-
14-// A writer for one helper call: each cell goes into air, over the same block, or over a `replace` block only.
15-function writer(g, replace = null) {
16-  const t = { placed: 0, refused: 0 };
17-  const at = (p, block, state, nbt) => {
18-    const [x, y, z] = p;
19-    const cur = g.inBounds(x, y, z) ? g.blockAt(x, y, z) : null;
20-    if (!cur || !(AIR.test(cur) || cur === id(block) || (replace && matches(replace, cur)))) { t.refused++; return; }
21-    const before = g.refused?.length ?? 0;
22-    g.set(x, y, z, block, state, nbt);
23-    if ((g.refused?.length ?? 0) > before) t.refused++;
24-    else t.placed++;
25-  };
26-  return { at, t };
27-}
28-
29-// Fill the inclusive box a..b with one block (state optional).
30-const fill = (W, a, b, block, state) => {
31-  for (let x = Math.min(a[0], b[0]); x <= Math.max(a[0], b[0]); x++)
--
