85-  fill(W, [x0, y0 + 9, zp], [x1, y0 + 9, zp], ...B.slab("smooth_sandstone", "top"));
86-  return W.t;
87-}
88-
89-// Stair flight: one oak_stairs per step from (x, y0, z0), rising in `dir`, `width` wide across the run (+x for north/south,
90-// +z for east/west). Two clear cells above each step are checked, not carved (lanesBlocked counts any that are not air).
91-// rail "+" or "-" puts a dark_oak_fence on that open side at each step's top.
92-export function flight(g, x, y0, y1, z0, dir = "north", { width = 2, rail = null } = {}) {
93-  const W = writer(g, null), [dx, , dz] = DIRS[dir];
94-  const across = dir === "north" || dir === "south" ? [1, 0, 0] : [0, 0, 1];
95-  let lanesBlocked = 0;
96-  for (let i = 0; i <= y1 - y0; i++) {
97-    const y = y0 + i, bx = x + i * dx, bz = z0 + i * dz;
98-    for (let w = 0; w < width; w++) {
99-      const px = bx + w * across[0], pz = bz + w * across[2];
100-      W.at([px, y, pz], ...B.stairs("oak", dir, "bottom"));
101-      for (let k = 1; k <= 2; k++) if (!AIR.test(g.blockAt(px, y + k, pz))) lanesBlocked++;
102-    }
103-    if (rail) {
104-      const side = rail === "+" ? width : -1;
105-      W.at([bx + side * across[0], y + 1, bz + side * across[2]], "dark_oak_fence", {});
106-    }
107-  }
