export function reservedCells(layout) {
  const out = new Set();
  for (const s of layout.sockets) {
    const counter = new Set(s.counter.map(k));
    for (const p of boxCells(s)) if (!counter.has(k(p))) out.add(k(p));
    for (const p of s.ceiling) out.add(k(p));
  }
  return out;
}

/** What the building places for the sockets: glass wall lines and back walls, a spawn-proof pit floor (rule 8: the empty
 *  envelope must not be a dark spawning pit), and the 2 counter cells in front of every payment hopper. */
export function socketFitout(layout, { counter = "smooth_stone_slab", glass = "light_gray_stained_glass", pit = "light_gray_stained_glass" } = {}) {
  const out = [], seen = new Set();
  const put = (p, b, st) => { if (!seen.has(k(p))) { seen.add(k(p)); out.push([...p, b, st]); } };
  const ctr = counter.endsWith("_slab") ? [counter, { type: "double", waterlogged: "false" }] : [counter, undefined];
  for (const s of layout.sockets) {
    for (const p of s.counter) put(p, ...ctr);
    for (const p of s.backWall) put(p, glass);
    for (const p of s.pit) put(p, pit);
  }
  for (const w of layout.wallLines) for (const p of w.cells) put(p, glass);
  return out;
}

/**
 * The envelope rules on a built grid. Hard problems (rules 1-4, 6, 9 and the wall lines) fail the check; light,
 * keeper access and the street clearances are reported too. light(x,y,z) -> block light, when known.
 */
